import json,collections
encs={}
for l in open('Encounter.ndjson'):
    d=json.loads(l); encs[d['id']]=d
def isclin(eid):
    e=encs.get(eid)
    return bool(e and e['class']['code']=='AMB' and 'CMED' in json.dumps(e.get('serviceType') or {}))
mr=json.load(open('mr.json'))
ac=['warfarin','apixaban','rivaroxaban','dabigatran','edoxaban','enoxaparin']
rows=[m for m in mr if isclin(m['enc']) and any(a in m['name'].lower() for a in ac)]
