cd /w && python3 - <<'EOF'
import json,collections
pats={}
for p in json.load(open('patients.json'))['resources']: pats[p['id']]=p
encs={}
for l in open('Encounter.ndjson'):
    d=json.loads(l); encs[d['id']]=d
byp=collections.defaultdict(list)
for l in open('Condition.ndjson'):
    d=json.loads(l)
    disp=' | '.join((c.get('display') or '')+'['+c.get('code','')+']' for c in d['code']['coding'])
    dl=disp.lower()
    if ('fibrillat' in dl and 'atrial' in dl) or 'atrial flutter' in dl:
        e=encs.get(d.get('encounter',{}).get('reference','').split('/')[-1])
        t=(e or {}).get('period',{}).get('start','?')
        byp[d['subject']['reference'].split('/')[-1]].append((t[:10],disp,d['id']))
for p,v in sorted(byp.items(),key=lambda x:min(i[0] for i in x[1])):
    dead=pats[p].get('deceasedDateTime')
    print(('DEAD ' if dead else 'LIVE '),p, 'n=',len(v), sorted(set(i[0] for i in v))[:3],'...',sorted(set(i[0] for i in v))[-1], set(i[1] for i in v))
EOF

